        tailService.confirm(job.id(), new TailConfirmRequest("m13-cf", "甲\n乙", "C10", 1));
        // 同键异参（去掉分隔符）：指纹须区分，返回 409 而非重放
        assertThrows(ConflictException.class, () -> tailService.confirm(job.id(),
                new TailConfirmRequest("m13-cf", "甲乙", "C10", 1)));
    }
